    24	
    25	type DirectionalRelation = Pick<
    26	  DiscourseRelation,
    27	  "label" | "complement" | "source" | "destination"
    28	>;
    29	
    30	export const getDirectionalRelationLabel = ({
    31	  relation,
    32	  sourceNodeType,
    33	  targetNodeType,
    34	}: {
    35	  relation: DirectionalRelation;
    36	  sourceNodeType: string;
    37	  targetNodeType: string;
    38	}): string => {
    39	  const { isReverse } = checkConnectionType(
    40	    relation,
    41	    sourceNodeType,
    42	    targetNodeType,
    43	  );
    44	  return isReverse && relation.complement
    45	    ? relation.complement
    46	    : relation.label;
    47	};
    48	
    49	export const persistRelationArrow = async ({
    50	  editor,
    51	  arrow,
    52	  targetId,
    53	}: {
    54	  editor: Editor;
    55	  arrow: DiscourseRelationShape;
    56	  targetId: TLShapeId;
    57	}): Promise<void> => {
    58	  const util = editor.getShapeUtil(arrow);
    59	  if (
    60	    util instanceof BaseDiscourseRelationUtil &&
    61	    "handleCreateRelationsInRoam" in util
    62	  ) {
    63	    type UtilWithRoamPersistence = BaseDiscourseRelationUtil & {
    64	      handleCreateRelationsInRoam: (args: {
    65	        arrow: DiscourseRelationShape;
    66	        targetId: TLShapeId;
    67	      }) => Promise<void>;
    68	    };
    69	    await (util as UtilWithRoamPersistence).handleCreateRelationsInRoam({
    70	      arrow,
    71	      targetId,
    72	    });
    73	  }
    74	};
    75	
    76	export const getValidRelationTypesBetween = (
    77	  editor: Editor,
    78	  startId: TLShapeId,
    79	  endId: TLShapeId,
    80	): RelationTypeOption[] => {
    81	  const startNode = editor.getShape(startId);
    82	  const endNode = editor.getShape(endId);
    83	  if (!startNode || !endNode) return [];
    84	  if (
    85	    !isDiscourseNodeShape(editor, startNode) ||
    86	    !isDiscourseNodeShape(editor, endNode)
    87	  )
    88	    return [];
    89	
    90	  const startNodeType = getDiscourseNodeTypeId({ shape: startNode });
    91	  const endNodeType = getDiscourseNodeTypeId({ shape: endNode });
    92	
    93	  const colorPalette = DefaultColorThemePalette.lightMode;
    94	  const validTypes: RelationTypeOption[] = [];
    95	  const seenLabels = new Set<string>();
    96	
    97	  for (const relation of getCreatableRelations()) {
    98	    if (!isRelationComplete(relation)) continue;
    99	    const { isDirect, isReverse } = checkConnectionType(
   100	      relation,
   101	      startNodeType,
   102	      endNodeType,
   103	    );
   104	    if (!isDirect && !isReverse) continue;
   105	
   106	    const label = getDirectionalRelationLabel({
   107	      relation,
   108	      sourceNodeType: startNodeType,
   109	      targetNodeType: endNodeType,
   110	    });
   111	    if (seenLabels.has(label)) continue;
   112	    seenLabels.add(label);
   113	
   114	    const hexColor =
   115	      colorPalette[getRelationColor(relation.label)]?.solid ?? "#333";
   116	    validTypes.push({ id: relation.id, label, color: hexColor });
   117	  }
   118	
   119	  return validTypes;
   120	};
   121	
   122	export const createDefaultRelationBetweenNodes = async ({
   123	  editor,
   124	  relationId,
   125	  sourceId,
   126	  targetId,
   127	}: {
   128	  editor: Editor;
   129	  relationId: string;
   130	  sourceId: TLShapeId;
   131	  targetId: TLShapeId;
   132	}): Promise<TLShapeId | null> => {
   133	  const selectedRelation = getCreatableRelations().find(
