   136	  if (!selectedRelation) return null;
   137	
   138	  const sourceNode = editor.getShape(sourceId);
   139	  const targetNode = editor.getShape(targetId);
   140	  if (
   141	    !sourceNode ||
   142	    !targetNode ||
   143	    !isDiscourseNodeShape(editor, sourceNode) ||
   144	    !isDiscourseNodeShape(editor, targetNode)
   145	  )
   146	    return null;
   147	  const label = getDirectionalRelationLabel({
   148	    relation: selectedRelation,
   149	    sourceNodeType: getDiscourseNodeTypeId({ shape: sourceNode }),
   150	    targetNodeType: getDiscourseNodeTypeId({ shape: targetNode }),
   151	  });
   152	
   153	  const sourceBounds = editor.getShapePageBounds(sourceId);
   154	  if (!sourceBounds) return null;
   155	
   156	  const color = getRelationColor(selectedRelation.label);
   157	  const arrowId = createShapeId();
   158	  editor.createShape<DiscourseRelationShape>({
   159	    id: arrowId,
   160	    type: DISCOURSE_RELATION_SHAPE_TYPE,
   161	    x: sourceBounds.midX,
   162	    y: sourceBounds.midY,
   163	    props: {
   164	      color,
   165	      labelColor: color,
   166	      text: label,
   167	      relationTypeId: relationId,
   168	      dash: "draw",
   169	      size: "m",
   170	      fill: "none",
   171	      bend: 0,
   172	      start: { x: 0, y: 0 },
   173	      end: { x: 0, y: 0 },
   174	      arrowheadStart: "none",
   175	      arrowheadEnd: "arrow",
