export const createAllRelationShapeUtils =
  (): TLShapeUtilConstructor<DiscourseRelationShape>[] => {
    class DiscourseRelationUtil extends BaseDiscourseRelationUtil {
      static override type = DISCOURSE_RELATION_SHAPE_TYPE;

      handleCreateRelationsInRoam = async ({
        arrow,
        targetId,
      }: {
        arrow: DiscourseRelationShape;
        targetId: TLShapeId;
      }) => {
        const editor = this.editor;
        const deleteAndWarn = (content: string) => {
          dispatchToastEvent({
            id: `tldraw-cancel-and-warn-${content}`,
            title: content,
            severity: "warning",
          });
          this.editor.deleteShapes([arrow.id]);
        };
        const target = editor.getShape(targetId);
        const bindings = editor.getBindingsFromShape(
          arrow,
          getDiscourseRelationBindingType({ shape: arrow }),
        );
        const sourceId = bindings.find((b) => b.toId !== targetId)?.toId;
        if (!sourceId) return;
        const source = editor.getShape(sourceId);
        if (!target || !source) return;
        if (
          !isDiscourseNodeShapeTypeGuard(target) ||
          !isDiscourseNodeShapeTypeGuard(source)
        ) {
          return deleteAndWarn(
            "Invalid shape type. Expected a DiscourseNodeShape.",
          );
        }
        const relationTypeId = getDiscourseRelationTypeId({ shape: arrow });
        const relation = getDiscourseRelationById(relationTypeId);
        if (!relation) return;

        const sourceNodeType = getDiscourseNodeTypeId({ shape: source });
        const targetNodeType = getDiscourseNodeTypeId({ shape: target });

        // Check all relations with the same label for a match
        const {
          isDirect,
          isReverse,
          matchingRelation: foundRelation,
        } = this.checkConnectionTypeAcrossLabel({
          label: relation.label,
          sourceNodeType,
          targetNodeType,
        });
        const matchingRelation = foundRelation ?? relation;

        if (!isDirect && !isReverse) {
          const validTargets = this.getValidTargetTypes(
            relation.label,
            sourceNodeType,
          );
          const uniqueTargetTexts = validTargets.map(
            (t) => discourseContext.nodes[t]?.text || t,
          );
          return deleteAndWarn(
            `Target node must be of type ${uniqueTargetTexts.join(", ")}`,
          );
        }

        if (matchingRelation.id !== relationTypeId) {
          editor.updateShapes<DiscourseRelationShape>([
            {
              id: arrow.id,
              type: arrow.type,
              props: { relationTypeId: matchingRelation.id },
            },
          ]);
        }
        if (getStoredRelationsEnabled()) {
          const sourceAsDNS = asDiscourseNodeShape(source, editor);
          const targetAsDNS = asDiscourseNodeShape(target, editor);

          if (sourceAsDNS && targetAsDNS) {
            const isOriginal = isDirect;
            await createReifiedRelation({
              sourceUid: isOriginal
                ? sourceAsDNS.props.uid
                : targetAsDNS.props.uid,
              destinationUid: isOriginal
                ? targetAsDNS.props.uid
                : sourceAsDNS.props.uid,
              relationBlockUid: matchingRelation.id,
            });
          } else {
            void internalError({
              error: "attempt to create a relation between non discourse nodes",
              type: "Canvas create relation",
            });
          }
        } else {
          const { triples } = matchingRelation;
          const isOriginal = isDirect;

          const newTriples = triples
            .map((t) => {
              if (/is a/i.test(t[1])) {
                const targetNode =
                  (t[2] === "source" && isOriginal) ||
                  (t[2] === "destination" && !isOriginal)
                    ? source
                    : target;
                const { title, uid } =
                  targetNode.props as DiscourseNodeShape["props"];
                return [
                  t[0],
                  isPageUid(uid) ? "has title" : "with uid",
                  isPageUid(uid) ? title : uid,
                ];
              }
              return t.slice(0);
            })
            .map(([source, relation, target]) => ({
              source,
              relation,
              target,
            }));
          // Get canvas page UID from the DOM (supports multiple canvases)
          const canvasPageUid = getCanvasPageUidFromDOM();
          if (!canvasPageUid) {
            return deleteAndWarn("No canvas page UID found");
          }
          const title = getPageTitleByPageUid(canvasPageUid);
          await triplesToBlocks({
            defaultPageTitle: `Auto generated from [[${title}]]`,
            toPage: async (title: string, blocks: InputTextNode[]) => {
              const parentUid =
                getPageUidByPageTitle(title) ||
                (await createPage({ title: title }));

              await Promise.all(
                blocks.map((node, order) =>
                  createBlock({ node, order, parentUid }).catch(() =>
                    console.error(
                      `Failed to create block: ${JSON.stringify(
                        { node, order, parentUid },
                        null,
                        4,
                      )}`,
                    ),
                  ),
                ),
              );
              await openBlockInSidebar(parentUid);
            },
            nodeSpecificationsByLabel: Object.fromEntries(
              Object.values(discourseContext.nodes).map((n) => [
                n.text,
                n.specification,
              ]),
            ),
          })(newTriples)();
        }
        refreshDiscourseContextsForMutatedUids({
          uids: [source.props.uid, target.props.uid],
        });
      };

      override getDefaultProps(): DiscourseRelationShape["props"] {
        return {
          dash: "draw",
          size: "m",
          fill: "none",
          color: COLOR_ARRAY[0],
          labelColor: COLOR_ARRAY[0],
          bend: 0,
          start: { x: 0, y: 0 },
          end: { x: 0, y: 0 },
          arrowheadStart: "none",
          arrowheadEnd: "arrow",
          text: "",
          labelPosition: 0.5,
          font: "draw",
          scale: 1,
          relationTypeId: null,
        };
      }
      override onHandleDrag: TLOnHandleDragHandler<DiscourseRelationShape> = (
        shape,
        { handle, isPrecise },
      ) => {
        const handleId = handle.id as ARROW_HANDLES;
        const bindings = getArrowBindings(this.editor, shape);
        const relationTypeId = getDiscourseRelationTypeId({ shape });
        const relationBindingType = getDiscourseRelationBindingType({ shape });

        if (handleId === ARROW_HANDLES.MIDDLE) {
          // Bending the arrow...
          const { start, end } = getArrowTerminalsInArrowSpace(
            this.editor,

    getFillDefForCanvas(),
    { key: `arrow:dot`, component: ArrowheadDotDef },
    { key: `arrow:cross`, component: ArrowheadCrossDef },
  ];
}

checkConnectionType(
  relation: { source: string; destination: string },
  sourceNodeType: string,
  targetNodeType: string,
): { isDirect: boolean; isReverse: boolean } {
  return checkConnectionType(relation, sourceNodeType, targetNodeType);
}

checkConnectionTypeAcrossLabel({
  label,
  sourceNodeType,
  targetNodeType,
  includeProvisional,
}: {
  label: string;
  sourceNodeType: string;
  targetNodeType: string;
  includeProvisional?: boolean;
}): {
  isDirect: boolean;
  isReverse: boolean;
  matchingRelation: DiscourseRelation | null;
} {
  const relationsWithLabel = includeProvisional
    ? discourseContext.relations[label]
    : discourseContext.relations[label]?.filter(isAcceptedRelationSchema);
  if (!relationsWithLabel) {
    return { isDirect: false, isReverse: false, matchingRelation: null };
  }

  for (const rel of relationsWithLabel) {
    const { isDirect, isReverse } = this.checkConnectionType(
      rel,
      sourceNodeType,
      targetNodeType,
    );
    if (isDirect || isReverse) {
      return { isDirect, isReverse, matchingRelation: rel };
    }
  }

  return { isDirect: false, isReverse: false, matchingRelation: null };
}

getValidTargetTypes(label: string, sourceNodeType: string): string[] {
  const relationsWithLabel = discourseContext.relations[label]?.filter(
    isAcceptedRelationSchema,
  );
  if (!relationsWithLabel) return [];

  const targets = new Set<string>();
  for (const rel of relationsWithLabel) {
    if (rel.source === sourceNodeType) targets.add(rel.destination);
    if (rel.destination === sourceNodeType) targets.add(rel.source);
  }
  return [...targets];
}

isValidNodeConnection(
  sourceNodeType: string,
  targetNodeType: string,
  relationId: string,
): boolean {
  const relations = Object.values(discourseContext.relations).flat();
  const relation = relations.find((r) => r.id === relationId);
  if (!relation) return false;

  // Validates handle drags of arrows that already exist, so provisional
  // relations stay re-bindable; only creation paths filter them out.
  const { isDirect, isReverse } = this.checkConnectionTypeAcrossLabel({
    label: relation.label,
    sourceNodeType,
    targetNodeType,
    includeProvisional: true,
  });
  return isDirect || isReverse;
}

